#include <iostream>
#include <vector>

namespace Pedido {
    bool datos_validos(const std::vector<int>& piezas) {
        if (piezas.size() > 6) {
            return false;
        }
        for (int cantidad : piezas) {
            if (cantidad < 0 || cantidad > 20) {
                return false;
            }
        }
        return true;
    }
}

namespace Estuches {
    int necesarios(int piezas) {
        return (piezas + 3) / 4;
    }
}

namespace Cajas {
    int necesarios(int piezas) {
        return (piezas + 6) / 7;
    }
}

int main() {
    const std::vector<int> piezas = {0, 7, 15};
    if (!Pedido::datos_validos(piezas)) {
        std::cout << "Pedido invalido";
        return 0;
    }

    using Estuches::necesarios;
    int total_estuches = 0;
    int total_cajas = 0;
    for (int cantidad : piezas) {
        total_estuches += necesarios(cantidad);
        total_cajas += Cajas::necesarios(cantidad);
    }
    std::cout << "Estuches: " << total_estuches;
    std::cout << "\nCajas: " << total_cajas;
    return 0;
}

